package b_list;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
public class Main {
// 메서드 정의
// 1.이름 나이를 전달받아 학생을 등록하는 메서드
List<Student> addStudent(String name, int age, List<Student> list) {
// 학생 객체 생성
Student st = new Student(name, age);
// 학생 객체 리스트에 추가
list.add(st);
return list; //학생의 정보를 추가한 리스트 반환 (void -> List<student>변경)
}
// 2) 전체 학생 정보 출력 메서드
void printAll(List<Student>list) {
for(int i=0;i<list.size(); i++) {
System.out.println((i+1)+"번째 학생 정보");
System.out.println(list.get(i));
System.out.println();
}
}
// 3) 특정 학생 등록 유무 확인 메서드
boolean findStudent(List<Student>list, String find) {
for(Student stu:list) {
if(stu.name.equals(find)){
return true;
}
}
// 같은 이름을 학생 리스트에서 찾지 못할 경우
return false; //void => boolean
}
public static void main(String[] args) {
Scanner sc = new Scanner(System.in);
Main m = new Main();
// 학생들의 정보를 저장할 리스트 생성
List<Student> stuList = new ArrayList();
System.out.println("=====학생 관리 프로그램=====");
while(true) {
System.out.println();
System.out.println("===이용할 기능 선택===");
System.out.println("1.학생 등록\n2.전체 학생 정보 출력");
System.out.println("3.특정 학생 확인 등록 유무 확인\n4.프로그램 종료.\n");
System.out.print("번호 입력 : ");
int choice = sc.nextInt();
if (choice ==1) {
System.out.println("학생 등록을 시작합니다");
System.out.println();
// 학생의 이름과 나이를 입력받아, 리스트에 저장
System.out.print("학생의 이름 : ");
String name = sc.next();
System.out.print("학생의 나이 : ");
int age = sc.nextInt();
// 학생 등록 메서드 호출
stuList = m.addStudent(name, age, stuList);
System.out.println(stuList);
}else if(choice ==2) {
System.out.println("전체 학생 정보 출력");
// 전체 학생 정보 출력하는 메서드 호출
m.printAll(stuList);
}else if(choice ==3) {
System.out.print("조회할 학생 이름 입력 : ");
String find = sc.next();
// 특정 학생의 이름이 리스트에 있는지 확인하는 메서드 호출
boolean check = m.findStudent(stuList, find);
System.out.println(find + "학생은 리스트에 " + (check?"등록되어 있습니다.":"등록되어 있지 않습니다."));
}else if(choice ==4) {
System.out.println("프로그램 종료");
break; //무한루프 탈출
}else {
System.out.println("1~4를 입력하세요!");
}
}
}
